[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --black: #000000;
      --purple: #7638FA;
      --orange: #FF7A00;
      --purple-light: #EDE5FF;
      --orange-light: #FFF0E0;
      --bg: #FFFFFF;
      --text: #1A1A1A;
      --text-muted: #6B7280;
      --border: #E5E7EB;
      --radius: 16px;
      --radius-sm: 10px;
      --radius-pill: 999px;
      --font: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      color: var(--text);
      background: var(--bg);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }

    /* ─── HEADER ─── */
    .header {
      position: fixed; top: 0; left: 0; right: 0; z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
      height: 64px;
      display: flex; align-items: center; justify-content: space-between;
      padding: 0 24px;
    }
    .header-logo {
      font-size: 1.35rem; font-weight: 800; letter-spacing: -0.02em;
      background: linear-gradient(135deg, var(--purple), var(--orange));
      -webkit-background-clip: text; -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .header-right { display: flex; align-items: center; gap: 16px; }
    .btn-login {
      background: var(--black); color: #fff;
      border: none; border-radius: var(--radius-pill);
      padding: 9px 22px; font-size: 0.9rem; font-weight: 600;
      cursor: pointer; font-family: var(--font);
      transition: opacity 0.2s;
    }
    .btn-login:hover { opacity: 0.85; }

    /* Hamburger */
    .hamburger {
      display: none; background: none; border: none; cursor: pointer;
      width: 36px; height: 36px; position: relative; z-index: 110;
    }
    .hamburger span {
      display: block; width: 22px; height: 2.5px; background: var(--black);
      border-radius: 2px; position: absolute; left: 7px;
      transition: all 0.3s ease;
    }
    .hamburger span:nth-child(1) { top: 10px; }
    .hamburger span:nth-child(2) { top: 17px; }
    .hamburger span:nth-child(3) { top: 24px; }
    .hamburger.active span:nth-child(1) { top: 17px; transform: rotate(45deg); }
    .hamburger.active span:nth-child(2) { opacity: 0; }
    .hamburger.active span:nth-child(3) { top: 17px; transform: rotate(-45deg); }

    /* Mobile nav overlay */
    .mobile-nav {
      display: none; position: fixed; inset: 0; z-index: 99;
      background: rgba(255,255,255,0.98);
      backdrop-filter: blur(16px);
      padding: 90px 32px 32px;
      opacity: 0; transition: opacity 0.3s ease;
    }
    .mobile-nav.open { display: flex; flex-direction: column; opacity: 1; }
    .mobile-nav a {
      font-size: 1.4rem; font-weight: 600; padding: 14px 0;
      border-bottom: 1px solid var(--border); display: block;
      transition: color 0.2s;
    }
    .mobile-nav a:hover { color: var(--purple); }

    @media (max-width: 768px) {
      .hamburger { display: block; }
    }

    /* ─── HERO ─── */
    .hero {
      min-height: 92vh; display: flex; align-items: center; justify-content: center;
      text-align: center; padding: 120px 24px 80px;
      position: relative; overflow: hidden;
      background: linear-gradient(160deg, #fff 0%, var(--purple-light) 40%, var(--orange-light) 100%);
    }
    .hero::before {
      content: ''; position: absolute; top: -120px; right: -120px;
      width: 500px; height: 500px; border-radius: 50%;
      background: radial-gradient(circle, rgba(118,56,250,0.18) 0%, transparent 70%);
      pointer-events: none;
    }
    .hero::after {
      content: ''; position: absolute; bottom: -80px; left: -80px;
      width: 400px; height: 400px; border-radius: 50%;
      background: radial-gradient(circle, rgba(255,122,0,0.14) 0%, transparent 70%);
      pointer-events: none;
    }
    .hero-content { max-width: 780px; position: relative; z-index: 1; }
    .hero h1 {
      font-size: clamp(2.4rem, 5.5vw, 4rem); font-weight: 800;
      line-height: 1.1; letter-spacing: -0.03em; margin-bottom: 24px;
    }
    .hero h1 .gradient-text {
      background: linear-gradient(135deg, var(--purple), var(--orange));
      -webkit-background-clip: text; -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .hero p {
      font-size: 1.2rem; color: var(--text-muted); margin-bottom: 36px;
      max-width: 560px; margin-left: auto; margin-right: auto;
    }
    .btn-primary {
      display: inline-flex; align-items: center; gap: 8px;
      background: linear-gradient(135deg, var(--purple), var(--orange));
      color: #fff; border: none; border-radius: var(--radius-pill);
      padding: 16px 36px; font-size: 1.05rem; font-weight: 700;
      cursor: pointer; font-family: var(--font);
      transition: transform 0.2s, box-shadow 0.2s;
      box-shadow: 0 4px 24px rgba(118,56,250,0.3);
    }
    .btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 32px rgba(118,56,250,0.4); }

    /* ─── SECTION SHARED ─── */
    .section { padding: 96px 24px; }
    .section-inner { max-width: 1120px; margin: 0 auto; }
    .section-label {
      font-size: 0.8rem; font-weight: 700; text-transform: uppercase;
      letter-spacing: 0.08em; color: var(--purple); margin-bottom: 12px;
    }

    /* ─── FEATURES ─── */
    .features {
      background: var(--bg);
    }
    .features-grid {
      display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
      gap: 24px; margin-top: 40px;
    }
    .feature-card {
      background: #FAFAFA; border-radius: var(--radius); padding: 32px 28px;
      border: 1px solid var(--border);
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .feature-card:hover { transform: translateY(-4px); box-shadow: 0 12px 32px rgba(0,0,0,0.06); }
    .feature-icon {
      width: 48px; height: 48px; border-radius: 12px;
      display: flex; align-items: center; justify-content: center;
      font-size: 1.4rem; margin-bottom: 18px;
    }
    .feature-icon.clips { background: linear-gradient(135deg, var(--purple), #A855F7); color: #fff; }
    .feature-icon.stories { background: linear-gradient(135deg, #E040FB, var(--orange)); color: #fff; }
    .feature-icon.dms { background: linear-gradient(135deg, var(--purple), #3B82F6); color: #fff; }
    .feature-icon.explore { background: linear-gradient(135deg, var(--orange), #EF4444); color: #fff; }
    .feature-card h3 { font-size: 1.15rem; font-weight: 700; margin-bottom: 8px; }
    .feature-card p { font-size: 0.92rem; color: var(--text-muted); line-height: 1.5; }
    .section-link {
      display: inline-flex; align-items: center; gap: 4px;
      font-weight: 700; font-size: 1rem; margin-top: 36px;
      color: var(--purple); transition: gap 0.2s;
    }
    .section-link:hover { gap: 8px; }

    /* ─── SAFETY ─── */
    .safety {
      background: linear-gradient(180deg, #F8F5FF 0%, #FFFFFF 100%);
    }
    .safety-layout {
      display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: center;
    }
    .safety-text h2 {
      font-size: clamp(1.8rem, 3.5vw, 2.6rem); font-weight: 800;
      line-height: 1.15; letter-spacing: -0.02em; margin-bottom: 18px;
    }
    .safety-text p { color: var(--text-muted); font-size: 1.05rem; margin-bottom: 24px; line-height: 1.65; }
    .safety-badges {
      display: grid; grid-template-columns: 1fr 1fr; gap: 16px;
    }
    .safety-badge {
      background: #fff; border-radius: var(--radius-sm); padding: 20px;
      border: 1px solid var(--border); text-align: center;
      transition: box-shadow 0.2s;
    }
    .safety-badge:hover { box-shadow: 0 4px 16px rgba(118,56,250,0.08); }
    .safety-badge-icon { font-size: 1.6rem; margin-bottom: 8px; }
    .safety-badge span { font-size: 0.85rem; font-weight: 600; display: block; }

    /* ─── CREATORS ─── */
    .creators {
      background: linear-gradient(135deg, #1A0033 0%, #0D001A 100%);
      color: #fff; position: relative; overflow: hidden;
    }
    .creators::before {
      content: ''; position: absolute; top: -60px; right: -60px;
      width: 400px; height: 400px; border-radius: 50%;
      background: radial-gradient(circle, rgba(118,56,250,0.25) 0%, transparent 70%);
    }
    .creators::after {
      content: ''; position: absolute; bottom: -80px; left: -40px;
      width: 350px; height: 350px; border-radius: 50%;
      background: radial-gradient(circle, rgba(255,122,0,0.2) 0%, transparent 70%);
    }
    .creators .section-inner { position: relative; z-index: 1; }
    .creators h2 {
      font-size: clamp(1.8rem, 3.5vw, 2.6rem); font-weight: 800;
      line-height: 1.15; letter-spacing: -0.02em; margin-bottom: 18px;
    }
    .creators p { color: rgba(255,255,255,0.72); font-size: 1.05rem; margin-bottom: 28px; line-height: 1.65; max-width: 600px; }
    .section-link-light {
      display: inline-flex; align-items: center; gap: 4px;
      font-weight: 700; font-size: 1rem;
      background: linear-gradient(90deg, var(--orange), #FFB366);
      -webkit-background-clip: text; -webkit-text-fill-color: transparent;
      background-clip: text; transition: gap 0.2s;
    }
    .section-link-light:hover { gap: 8px; }
    .creators-stats {
      display: flex; gap: 48px; margin-top: 48px;
      padding-top: 40px; border-top: 1px solid rgba(255,255,255,0.1);
    }
    .creators-stat strong { font-size: 2rem; font-weight: 800; display: block; }
    .creators-stat strong .purple { color: var(--purple); }
    .creators-stat strong .orange { color: var(--orange); }
    .creators-stat span { font-size: 0.88rem; color: rgba(255,255,255,0.5); }

    /* ─── TAGLINE BANNER ─── */
    .tagline-banner {
      padding: 80px 24px;
      background: linear-gradient(135deg, var(--purple) 0%, var(--orange) 100%);
      text-align: center;
    }
    .tagline-banner h2 {
      font-size: clamp(1.6rem, 4vw, 2.8rem); font-weight: 800;
      color: #fff; letter-spacing: -0.02em; line-height: 1.2;
    }

    /* ─── NEWS ─── */
    .news { background: #FAFAFA; }
    .news-header {
      display: flex; justify-content: space-between; align-items: flex-end;
      margin-bottom: 32px;
    }
    .news-header h2 {
      font-size: clamp(1.6rem, 3vw, 2.2rem); font-weight: 800;
      letter-spacing: -0.02em;
    }
    .news-header .view-more {
      font-weight: 700; color: var(--purple); font-size: 0.95rem;
      display: inline-flex; align-items: center; gap: 4px;
      transition: gap 0.2s;
    }
    .news-header .view-more:hover { gap: 8px; }
    .news-carousel {
      display: flex; gap: 24px; overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      padding-bottom: 16px;
      scrollbar-width: thin;
      scrollbar-color: var(--purple) transparent;
    }
    .news-carousel::-webkit-scrollbar { height: 6px; }
    .news-carousel::-webkit-scrollbar-track { background: transparent; }
    .news-carousel::-webkit-scrollbar-thumb { background: var(--purple); border-radius: 3px; }
    .news-card {
      flex: 0 0 320px; scroll-snap-align: start;
      background: #fff; border-radius: var(--radius);
      border: 1px solid var(--border); overflow: hidden;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .news-card:hover { transform: translateY(-4px); box-shadow: 0 12px 32px rgba(0,0,0,0.08); }
    .news-thumb {
      width: 100%; height: 180px; position: relative; overflow: hidden;
    }
    .news-thumb-bg {
      width: 100%; height: 100%; display: flex; align-items: center; justify-content: center;
      font-size: 3rem;
    }
    .news-thumb-bg.purple-grad { background: linear-gradient(135deg, var(--purple), #A855F7); }
    .news-thumb-bg.orange-grad { background: linear-gradient(135deg, var(--orange), #FBBF24); }
    .news-thumb-bg.warm-grad { background: linear-gradient(135deg, #E040FB, var(--orange)); }
    .news-thumb-bg.teal-grad { background: linear-gradient(135deg, #06B6D4, var(--purple)); }
    .news-body { padding: 20px; }
    .news-tags { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 12px; }
    .news-tag {
      font-size: 0.7rem; font-weight: 700; text-transform: uppercase;
      letter-spacing: 0.04em; padding: 3px 10px; border-radius: var(--radius-pill);
      background: var(--purple-light); color: var(--purple);
    }
    .news-tag.orange { background: var(--orange-light); color: var(--orange); }
    .news-card h3 { font-size: 1rem; font-weight: 700; line-height: 1.4; margin-bottom: 10px; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
    .news-date { font-size: 0.82rem; color: var(--text-muted); }

    /* ─── CTA DOWNLOAD ─── */
    .cta-download {
      padding: 96px 24px; text-align: center;
      background: linear-gradient(180deg, #fff 0%, var(--purple-light) 100%);
    }
    .cta-download h2 {
      font-size: clamp(2rem, 4vw, 3rem); font-weight: 800;
      letter-spacing: -0.03em; margin-bottom: 8px;
    }
    .cta-download p {
      font-size: 1.2rem; color: var(--text-muted); margin-bottom: 36px;
    }
    .cta-buttons { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }
    .btn-store {
      display: inline-flex; align-items: center; gap: 10px;
      background: var(--black); color: #fff; border-radius: var(--radius-sm);
      padding: 14px 28px; font-family: var(--font);
      font-size: 0.9rem; font-weight: 600; cursor: pointer;
      border: none; transition: opacity 0.2s, transform 0.2s;
    }
    .btn-store:hover { opacity: 0.85; transform: translateY(-2px); }
    .btn-store svg { width: 22px; height: 22px; }
    .btn-store-text { text-align: left; line-height: 1.2; }
    .btn-store-text small { font-size: 0.65rem; font-weight: 400; opacity: 0.8; display: block; }
    .btn-store-text strong { font-size: 1rem; }

    /* ─── FOOTER ─── */
    .footer {
      background: var(--black); color: #fff; padding: 64px 24px 32px;
    }
    .footer-inner { max-width: 1120px; margin: 0 auto; }
    .footer-grid {
      display: grid; grid-template-columns: repeat(5, 1fr); gap: 32px;
      margin-bottom: 48px;
    }
    .footer-col h4 {
      font-size: 0.78rem; font-weight: 700; text-transform: uppercase;
      letter-spacing: 0.08em; color: rgba(255,255,255,0.4);
      margin-bottom: 16px;
    }
    .footer-col ul { list-style: none; }
    .footer-col li { margin-bottom: 10px; }
    .footer-col a {
      font-size: 0.88rem; color: rgba(255,255,255,0.75);
      transition: color 0.2s;
